@ExtendWith(MockitoExtension.class)
class StartAutoLoadPolicyTests {

    private SyncedEnforcer enforcer;

    @Mock
    private Model mockModel;

    @Mock
    private Adapter mockAdapter;

    @BeforeEach
    void setUp() {
        enforcer = new SyncedEnforcer(mockModel, mockAdapter);
    }

    @Test
    void testStartAutoLoadPolicy_SuccessfulStart() throws Exception {
        // Arrange
        long interval = 100L;

        // Act
        enforcer.startAutoLoadPolicy(interval);

        // Assert
        AtomicInteger autoLoadRunning = getAutoLoadRunningField();
        assertEquals(1, autoLoadRunning.get());

        // Wait a bit to ensure thread started
        Thread.sleep(50);

        // Verify loadPolicy was called at least once
        verify(mockAdapter, atLeastOnce()).loadPolicy(any());

        // Clean up
        enforcer.stopAutoLoadPolicy();
    }

    @Test
    void testStartAutoLoadPolicy_AlreadyRunning() throws Exception {
        // Arrange
        long interval = 100L;
        enforcer.startAutoLoadPolicy(interval);

        // Get initial thread reference
        Thread initialThread = getAutoLoadThread();

        // Act - Try to start again
        enforcer.startAutoLoadPolicy(interval);

        // Assert
        AtomicInteger autoLoadRunning = getAutoLoadRunningField();
        assertEquals(1, autoLoadRunning.get()); // Should still be 1

        // Verify same thread is still running
        Thread currentThread = getAutoLoadThread();
        assertSame(initialThread, currentThread);

        // Clean up
        enforcer.stopAutoLoadPolicy();
    }

    @Test
    void testStartAutoLoadPolicy_ZeroInterval() throws Exception {
        // Arrange
        long interval = 0L;

        // Act
        enforcer.startAutoLoadPolicy(interval);

        // Assert
        AtomicInteger autoLoadRunning = getAutoLoadRunningField();
        assertEquals(1, autoLoadRunning.get());

        // Wait a bit to ensure thread started
        Thread.sleep(50);

        // Verify loadPolicy was called multiple times due to zero interval
        verify(mockAdapter, atLeast(2)).loadPolicy(any());

        // Clean up
        enforcer.stopAutoLoadPolicy();
    }

    @Test
    @Timeout(value = 2000, unit = TimeUnit.MILLISECONDS)
    void testStartAutoLoadPolicy_MultipleLoads() throws Exception {
        // Arrange
        long interval = 50L;

        // Act
        enforcer.startAutoLoadPolicy(interval);

        // Wait for multiple intervals
        Thread.sleep(200);

        // Assert
        verify(mockAdapter, atLeast(3)).loadPolicy(any());

        // Clean up
        enforcer.stopAutoLoadPolicy();
    }

    @Test
    void testStartAutoLoadPolicy_NegativeInterval() throws Exception {
        // Arrange
        long interval = -100L;

        // Act
        enforcer.startAutoLoadPolicy(interval);

        // Assert
        AtomicInteger autoLoadRunning = getAutoLoadRunningField();
        assertEquals(1, autoLoadRunning.get());

        // Wait a bit to ensure thread started
        Thread.sleep(50);

        // Verify loadPolicy was called (negative interval should be treated as 0)
        verify(mockAdapter, atLeastOnce()).loadPolicy(any());

        // Clean up
        enforcer.stopAutoLoadPolicy();
    }

    @Test
    void testStartAutoLoadPolicy_ThreadInterruption() throws Exception {
        // Arrange
        long interval = 1000L; // Long interval to keep thread alive

        // Act
        enforcer.startAutoLoadPolicy(interval);

        // Get the thread
        Thread autoLoadThread = getAutoLoadThread();

        // Interrupt the thread
        autoLoadThread.interrupt();

        // Wait for thread to die
        autoLoadThread.join(100);

        // Assert
        assertFalse(autoLoadThread.isAlive());
        AtomicInteger autoLoadRunning = getAutoLoadRunningField();
        assertEquals(0, autoLoadRunning.get());
    }

    @Test
    void testStartAutoLoadPolicy_StopAndRestart() throws Exception {
        // Arrange
        long interval = 100L;

        // Start first time
        enforcer.startAutoLoadPolicy(interval);
        Thread.sleep(50);

        // Stop
        enforcer.stopAutoLoadPolicy();
        Thread.sleep(50);

        // Reset mock to count new calls
        reset(mockAdapter);

        // Act - Start again
        enforcer.startAutoLoadPolicy(interval);
        Thread.sleep(50);

        // Assert
        AtomicInteger autoLoadRunning = getAutoLoadRunningField();
        assertEquals(1, autoLoadRunning.get());
        verify(mockAdapter, atLeastOnce()).loadPolicy(any());

        // Clean up
        enforcer.stopAutoLoadPolicy();
    }

    @Test
    void testStartAutoLoadPolicy_WithDifferentConstructors() throws Exception {
        // Test with different constructors
        SyncedEnforcer enforcer1 = new SyncedEnforcer();
        SyncedEnforcer enforcer2 = new SyncedEnforcer("test_model.conf");
        SyncedEnforcer enforcer3 = new SyncedEnforcer("test_model.conf", "test_policy.csv");
        SyncedEnforcer enforcer4 = new SyncedEnforcer(mockModel);

        long interval = 100L;

        // All should start without exception
        enforcer1.startAutoLoadPolicy(interval);
        enforcer2.startAutoLoadPolicy(interval);
        enforcer3.startAutoLoadPolicy(interval);
        enforcer4.startAutoLoadPolicy(interval);

        // Clean up
        enforcer1.stopAutoLoadPolicy();
        enforcer2.stopAutoLoadPolicy();
        enforcer3.stopAutoLoadPolicy();
        enforcer4.stopAutoLoadPolicy();
    }

    @Test
    void testStartAutoLoadPolicy_ConcurrentAccess() throws Exception {
        // Arrange
        long interval = 100L;

        // Act - Start from multiple threads
        Thread t1 = new Thread(() -> enforcer.startAutoLoadPolicy(interval));
        Thread t2 = new Thread(() -> enforcer.startAutoLoadPolicy(interval));
        Thread t3 = new Thread(() -> enforcer.startAutoLoadPolicy(interval));

        t1.start();
        t2.start();
        t3.start();

        t1.join();
        t2.join();
        t3.join();

        // Assert - Only one should have succeeded
        AtomicInteger autoLoadRunning = getAutoLoadRunningField();
        assertEquals(1, autoLoadRunning.get());

        // Clean up
        enforcer.stopAutoLoadPolicy();
    }

    private AtomicInteger getAutoLoadRunningField() throws Exception {
        Field field = SyncedEnforcer.class.getDeclaredField("autoLoadRunning");
        field.setAccessible(true);
        return (AtomicInteger) field.get(enforcer);
    }

    private Thread getAutoLoadThread() throws Exception {
        Field field = SyncedEnforcer.class.getDeclaredField("autoLoadThread");
        field.setAccessible(true);
        return (Thread) field.get(enforcer);
    }
}

